#pragma once
#include <string>
namespace Generated {
    // FIX: уникальный разделитель raw-строки.
    static const std::string cmakeHelpFile = R"GEN(@CONTENT@)GEN";
}

#pragma once
#include <string>
namespace Generated {
    // FIX: уникальный разделитель raw-строки, чтобы содержимое
    // шаблонов не могло случайно закрыть R"(...)".
    static const std::string mainCppFile = R"GEN(@MAIN_CPP_CONTENT@)GEN";
    static const std::string projectCppFile = R"GEN(@PROJECT_CPP_CONTENT@)GEN";
    static const std::string projectHppFile = R"GEN(@PROJECT_HPP_CONTENT@)GEN";
}

#include <CPPTemplates/Project.hpp>

#include <string>
int main(int argc, char** argv) {

	using namespace OksEngine;

	ASSERT_FMSG(argc > 0, "First parameter must be config file name.");

	const Engine::CreateInfo engineCreateInfo{
		argc, argv
	};

	Engine engine{ engineCreateInfo };

	engine.Run();

	return 0;
}

// FIX: Реализация Engine::Engine и Engine::Update находится в
// ecs_generator3.cpp. Этот файл — шаблон для генерации проекта,
// он не должен компилироваться в текущей сборке (исключён в
// CMakeLists.txt через list(FILTER ... EXCLUDE REGEX "/CPPTemplates/")).
//
// Если вы хотите использовать Project.cpp как самостоятельную
// единицу трансляции — раскомментируйте реализацию ниже и
// удалите ecs_generator3.cpp, либо наоборот.

#include <CPPTemplates/Project.hpp>

#pragma once 

#include <memory>
#include <chrono>
#include <list>
#include <utility>

#include <ECS2.World.hpp>

namespace OksEngine {

	class Engine {
	public:

		struct CreateInfo {
			int argc_ = 0;
			char** argv_ = nullptr;
		};

		explicit Engine(const CreateInfo& createInfo) noexcept;

		void Run() {
			isRunning_ = true;
			//while (IsRunning()) {
				Update();
			//}

		}

		inline bool IsRunning() const noexcept {
			return isRunning_;
		}

		void Update() noexcept;

	private:
		bool isRunning_ = false;
		std::shared_ptr<class ECS2::World> world2_ = nullptr;
	};

}

# dump-project.ps1 param( [string]$Root = (Get-Location).Path, [string]$Output = "project_dump.xml", [int]$MaxFileSizeKb = 512, [switch]$IncludeAuto, # ���� ����� � �� ��������� auto_* ����� [switch]$IncludeBinary # ���� ����� � �� ��������� �� ���������� )
# --------------------------------------------------------------------------- # 1. ��������, ������� �� ������� # --------------------------------------------------------------------------- $excludeDirs = @( '.git', '.vs', '.vscode', '.idea', '.continue', 'Build', 'build', 'out', 'bin', 'obj', 'vcpkg_installed', 'node_modules', 'ImGui', # third-party 'CMakeTemplates_Generated', # ������������ CMake configure 'CPPTemplates_Generated' # ������������ CMake configure )
# --------------------------------------------------------------------------- # 2. ����������, ������� ������ # --------------------------------------------------------------------------- $extensions = @( '.hpp', '.h', '.cpp', '.cxx', '.cc', '.c', '.inl', '.ecs', '.ecs_module', '.ecs_package', '.lua', '.cmake', '.txt', '.md', '.json', '.yaml', '.yml', '.toml', '.ps1', '.sh', '.bat', '.py', '.in' )
# --------------------------------------------------------------------------- # 3. �������� Root # --------------------------------------------------------------------------- if (-not (Test-Path -LiteralPath $Root)) { Write-Error "Root path does not exist: $Root" exit 1 } $Root = (Resolve-Path -LiteralPath $Root).Path $outputPath = Join-Path $Root $Output
# --------------------------------------------------------------------------- # 4. ������ �������� ������ # --------------------------------------------------------------------------- function Test-BinaryFile { param([string]$Path) try { $fs = [System.IO.File]::OpenRead($Path) $buf = New-Object byte[] 1024 $n = $fs.Read($buf, 0, $buf.Length) $fs.Close() for ($i = 0; $i -lt $n; $i++) { if ($buf[$i] -eq 0) { return $true } } return $false } catch { return $true } }
# --------------------------------------------------------------------------- # 5. ���� ������ # --------------------------------------------------------------------------- $autoSkipped = 0
$files = Get-ChildItem -Path $Root -Recurse -File -Force | Where-Object {
$rel = $_.FullName.Substring($Root.Length + 1) $parts = $rel.Split([IO.Path]::DirectorySeparatorChar)
# ����������� �������� foreach ($p in $parts) { if ($excludeDirs -contains $p) { return $false } }
# ��� ���� if ($_.FullName -eq $outputPath) { return $false }
# ���������� if ($extensions -notcontains $_.Extension.ToLower()) { return $false }
# ������ if ($_.Length -gt ($MaxFileSizeKb * 1024)) { return $false }
# ---- �������: ���������� ������������������� ������ ---- if (-not $IncludeAuto) { if ($_.Name -like 'auto_*') { $script:autoSkipped++ return $false } }
return $true } | Sort-Object FullName
# --------------------------------------------------------------------------- # 6. ������ ����� (� �������������� XML-���������) # --------------------------------------------------------------------------- $utf8NoBom = New-Object System.Text.UTF8Encoding($false) $writer = New-Object System.IO.StreamWriter($outputPath, $false, $utf8NoBom)
try { $writer.WriteLine("<!-- Project dump -->") $writer.WriteLine("<!-- Root: $Root -->") $writer.WriteLine("<!-- Auto-generated files excluded: $(-not $IncludeAuto) -->") $writer.WriteLine("<!-- Files: $($files.Count) -->") $writer.WriteLine()
$i = 0 $totalBytes = 0 $written = 0
foreach ($f in $files) { $i++ $rel = $f.FullName.Substring($Root.Length + 1).Replace('\', '/')
if ((-not $IncludeBinary) -and (Test-BinaryFile $f.FullName)) { Write-Host "[$i/$($files.Count)] SKIP (binary): $rel" continue }
$content = Get-Content -Path $f.FullName -Raw -Encoding UTF8 if ($null -eq $content) { $content = "" }
# ���������� XML-��������, ����� ���� ��� �������� XML # � ��������� �������������� �������. $escaped = [System.Security.SecurityElement]::Escape($content)
$writer.WriteLine("<file path=`"$rel`">") $writer.WriteLine("<content>") $writer.Write($escaped) $writer.WriteLine() $writer.WriteLine("</content>") $writer.WriteLine("</file>") $writer.WriteLine()
$totalBytes += $f.Length $written++ Write-Host "[$i/$($files.Count)] $rel" }
Write-Host "" Write-Host "Done: $outputPath" Write-Host "Files written: $written, auto_* skipped: $autoSkipped" Write-Host "Total source size: $([math]::Round($totalBytes / 1KB, 1)) KB" } finally { $writer.Close() }

// FIX: в дампе было <auto_OksEngine.RunSystems.hpp> и <Engine.hpp> —
// таких файлов нет. Используем существующие заголовки.
#include <auto_ecs_generator3.RunSystems.hpp>
#include <ecs_generator3.hpp>

#include <Common/CommandLineParameters/auto_OksEngine.CommandLineParameters.hpp>
#include <ECS/File/auto_OksEngine.ECS.File.hpp>

namespace OksEngine {

	Engine::Engine(const CreateInfo& createInfo) noexcept {

		OS::InitializeLogger(createInfo.argc_, createInfo.argv_);
		world2_ = std::make_shared<ECS2::World>();

		{
			const int argc = createInfo.argc_;
			char** argv = createInfo.argv_;

			const ECS2::Entity::Id commandLineParametersEntity = world2_->CreateEntity();
			world2_->CreateComponent<CommandLineParameters>(commandLineParametersEntity);
			world2_->CreateComponent<ExecutablePath>(commandLineParametersEntity, argv[0]);

			for (int i = 1; i < argc; i++) {

				const char* value = argv[i];
				using namespace std::string_literals;
				if (value == "-cfg"s) {
					world2_->CreateComponent<ConfigFilePath>(commandLineParametersEntity, argv[i + 1]);
				}
				if (value == "-scn"s) {
					world2_->CreateComponent<SceneParameter>(commandLineParametersEntity, argv[i + 1]);
				}
				if (value == "-ecs_project_file"s) {
					world2_->CreateComponent<ECS::Project::Path>(commandLineParametersEntity, argv[i + 1]);
				}
			}
		}

	}

	void Engine::Update() noexcept {

		HRESULT r;
		r = SetThreadDescription(GetCurrentThread(), L"Main thread");

		//CreateThreads(world2_);

		RunInitializeSystems(world2_);

		/*while (IsRunning()) {

			RunSystems(world2_);

		}*/

	}


}

