												CPP__TREE__EXPR__CREATE_LAMBDA(this,
													CPP::Tree::Expr::CaptureType::ByReference,
													std::vector<CPP::Tree::Expr::LambdaCapture>{},
													CPP__TREE__CREATE_ENTITIES_VECTOR(),
													CPP__TREE__STMT__CREATE_COMPOUND_STATEMENT(this,
