										CPP__TREE__CREATE_ENTITIES_VECTOR(
											//OksEngine::Test2::TestChild2System(world); or comment that system disabled
											[&]() -> ECS2::Entity::Id {

												if (ECS::File::Table::IsSystemDisabled(this, childSystemEntityId)) {
