namespace OksEngine {

	class ecs_generator3 {
	public:

		struct CreateInfo {
			int argc_ = 0;
			char** argv_ = nullptr;
		};

		explicit ecs_generator3(const CreateInfo& createInfo) noexcept;

		void Run() {
			isRunning_ = true;
			//while (IsRunning()) {
				Update();
			//}

		}

		inline bool IsRunning() const noexcept {
			return isRunning_;
		}

		void Update() noexcept;

	private:
		bool isRunning_ = false;
		std::shared_ptr<class ECS2::World> world2_ = nullptr;
	};

}

#include <ecs_generator3.hpp>

#include <string>
int main(int argc, char** argv) {

	ASSERT_FMSG(argc > 0, "First parameter must be config file name.");

	using namespace OksEngine;

	const ecs_generator3::CreateInfo engineCreateInfo{
		argc, argv
	};

	ecs_generator3 generator{ engineCreateInfo };

	generator.Run();

	return 0;
}

